content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-005

=== 用户原始指令 (query.txt) ===
帮我弄个防沉迷卡片，剩余时间会变，点开进app，红字警告

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个防沉迷卡片，剩余时间会变，点开进app，红字警告",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "antiAddiction": {
        "title": {
          "type": "string",
          "description": "防沉迷卡片标题",
          "sampleValue": "防沉迷"
        },
        "remainingTimeText": {
          "type": "string",
          "description": "当前可继续使用的剩余时间展示文本",
          "sampleValue": "15分"
        },
        "progressValue": {
          "type": "number",
          "description": "已使用时长进度值，接近或达到总时长时表示需要警告",
          "sampleValue": 45
        },
        "progressTotal": {
          "type": "number",
          "description": "当日可用总时长进度总量",
          "sampleValue": 60
        },
        "limitText": {
          "type": "string",
          "description": "当日健康使用时长上限展示文本",
          "sampleValue": "60分"
        },
        "warningText": {
          "type": "string",
          "description": "防沉迷红字警告展示文本",
          "sampleValue": "超时"
        },
        "actionLabel": {
          "type": "string",
          "description": "进入健康使用 App 设置页的短动作文本",
          "sampleValue": "进应用"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "计时图标，适合用于防沉迷、应用时长和剩余时间提醒场景。"
    }
  ]
}

